mapper.update:
update book_info
bookName = #{bookname,jdbcType=VARCHAR}, bookAuthor = #{bookauthor,jdbcType=VARCHAR}, bookPrice = #{bookprice,jdbcType=DECIMAL}, bookTypeId = #{booktypeid,jdbcType=INTEGER}, bookDesc = #{bookdesc,jdbcType=VARCHAR}, isBorrowed = #{isborrowed,jdbcType=TINYINT}, bookImg = #{bookimg,jdbcType=VARCHAR}, isOffShelf = #{isoffshelf,jdbcType=TINYINT},
where bookId = #{bookid,jdbcType=INTEGER}

mapper.select:
select bookId, bookName, bookAuthor, bookPrice, bookTypeId, bookDesc, isBorrowed, bookImg, isOffShelf, (select bookTypeName from book_type where book_type.bookTypeId = book_info.bookTypeId) as bookTypeName from book_info
and bookName like concat('%',#{bookname},'%') and bookAuthor like concat('%',#{bookauthor},'%') and bookTypeId = #{booktypeid} and isOffShelf = 1 and isBorrowed = 0 and isOffShelf = 0 and isBorrowed = 1
limit #{begin}, #{size}

select bookId, bookName, bookAuthor, bookPrice, bookTypeId, bookDesc, isBorrowed, bookImg, isOffShelf,
       (select bookTypeName from book_type where book_type.bookTypeId = book_info.bookTypeId) as bookTypeName
from book_info
and bookTypeId = #{booktypeid}
limit #{begin}, #{size}
